/**
 * Expand the HRP (human-readable part) for the bech32 checksum,
 * per the BIP-0173 reference algorithm.
 *
 * Returns [high 5 bits of each char code] + [0] + [low 5 bits of each char code].
 *
 * @param {string} hrp
 * @returns {number[]}
 */
export function bech32_hrp_expand(hrp) {
  const high = [];
  const low = [];
  for (let i = 0; i < hrp.length; i++) {
    const c = hrp.charCodeAt(i);
    high.push(c >> 5);
    low.push(c & 31);
  }
  return high.concat([0], low);
}

