/**
 * Generator constants for the BIP-0173 bech32 polymod checksum.
 * All values fit in 30 bits, so results stay non-negative with
 * unsigned shift operations.
 */
const GEN = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3];

/**
 * Compute the bech32 polymod checksum over a list of 5-bit values,
 * per the BIP-0173 reference algorithm.
 *
 * @param {number[]} values
 * @returns {number}
 */
export function bech32_polymod(values) {
  let chk = 1;
  for (const v of values) {
    const top = chk >>> 25;
    chk = ((chk & 0x1ffffff) << 5) ^ v;
    for (let i = 0; i < 5; i++) {
      if ((top >> i) & 1) {
        chk ^= GEN[i];
      }
    }
  }
  return chk;
}

