// Minimal argparse-compatible CLI parser for exactly two required string
// options `--a` and `--b`, mimicking Python's argparse behavior:
//   - supports `--a value` and `--a=value` forms
//   - `-h` / `--help` prints usage/help to stdout and exits 0
//   - missing required options print usage + error to stderr, exit 2
//   - unrecognized arguments print usage + error to stderr, exit 2

const OPTION_NAMES = ["--a", "--b"];

function usageLine(prog) {
  return `usage: ${prog} [-h] --a A --b B`;
}

function helpText(prog) {
  return (
    usageLine(prog) +
    "\n\n" +
    "options:\n" +
    "  -h, --help  show this help message and exit\n" +
    "  --a A\n" +
    "  --b B\n"
  );
}

function fail(prog, message) {
  process.stderr.write(usageLine(prog) + "\n");
  process.stderr.write(`${prog}: error: ${message}\n`);
  process.exit(2);
}

// True for tokens argparse would treat as an option string rather than a
// value: starts with '-' and is not a lone '-' or a negative number.
function looksLikeOption(token) {
  if (token.length < 2 || token[0] !== "-") return false;
  return !/^-\d+$|^-\d*\.\d+$/.test(token);
}

export function parseArgs(argv, prog) {
  const values = { a: undefined, b: undefined };
  const extras = [];

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];

    if (token === "-h" || token === "--help") {
      process.stdout.write(helpText(prog));
      process.exit(0);
    }

    let name = null;
    let inlineValue = null;

    if (token.startsWith("--")) {
      const eq = token.indexOf("=");
      const key = eq === -1 ? token : token.slice(0, eq);
      if (OPTION_NAMES.includes(key)) {
        name = key.slice(2);
        if (eq !== -1) inlineValue = token.slice(eq + 1);
      }
    }

    if (name !== null) {
      if (inlineValue !== null) {
        values[name] = inlineValue;
      } else {
        const next = argv[i + 1];
        if (next === undefined || looksLikeOption(next)) {
          fail(prog, `argument ${token}: expected one argument`);
        }
        values[name] = next;
        i++;
      }
    } else {
      extras.push(token);
    }
  }

  // argparse checks required arguments before reporting extras.
  const missing = [];
  if (values.a === undefined) missing.push("--a");
  if (values.b === undefined) missing.push("--b");
  if (missing.length > 0) {
    fail(prog, `the following arguments are required: ${missing.join(", ")}`);
  }

  if (extras.length > 0) {
    fail(prog, `unrecognized arguments: ${extras.join(" ")}`);
  }

  return { a: values.a, b: values.b };
}

